import{X as e,Y as t,ct as n,t as r}from"./chunks/framework.CaFWb3SA.js";var i=JSON.parse(`{"title":"Era 系列历史","description":"","frontmatter":{},"headers":[],"relativePath":"guide/History.md","filePath":"guide/History.md"}`),a={name:`guide/History.md`};function o(r,i,a,o,s,c){return n(),t(`div`,null,[...i[0]||=[e(`<h1 id="era-系列历史" tabindex="-1">Era 系列历史 <a class="header-anchor" href="#era-系列历史" aria-label="Permalink to “Era 系列历史”">​</a></h1><h2 id="前言" tabindex="-1">前言 <a class="header-anchor" href="#前言" aria-label="Permalink to “前言”">​</a></h2><p>了解一点历史，能帮我们理解“为什么脚本长这样”。Era 系列走过了一段不短的岁月，才形成今天的样子。这一节只是简略的脉络梳理，不求详尽，但求让你心里有张地图。</p><h2 id="eramaker-最早的引擎" tabindex="-1">Eramaker：最早的引擎 <a class="header-anchor" href="#eramaker-最早的引擎" aria-label="Permalink to “Eramaker：最早的引擎”">​</a></h2><p>Era 系列游戏的起点，是日本的 <strong>Eramaker</strong> 引擎。</p><p>它提供了一套用 <code>CSV</code> 描述数据、用 <code>ERB</code> 编写剧情的开发方式，让没有编程基础的人也能做出有数值、有剧情、可反复游玩的文字游戏。今天我们写脚本时用到的大量概念——函数、变量、<code>PRINT</code> 命令、内置流程——都能追溯到它。</p><p>不过，Eramaker 在功能、性能和兼容性上都有不少局限，后来渐渐停止了维护。</p><h2 id="emuera-兼容并扩展的后继者" tabindex="-1">Emuera：兼容并扩展的后继者 <a class="header-anchor" href="#emuera-兼容并扩展的后继者" aria-label="Permalink to “Emuera：兼容并扩展的后继者”">​</a></h2><p>为了在保持兼容的前提下解决 Eramaker 的问题，社区出现了以 <strong>Emuera</strong> 为代表的新引擎。</p><p>Emuera 用 C# 重写，基本完整地兼容了 Eramaker 的 <code>CSV</code> 与 <code>ERB</code>，同时对许多“不自然的行为”做了修正（比如数组越界、<code>RAND</code> 的取值范围等）。更重要的是，它<strong>扩展了大量新语法</strong>：</p><ul><li><code>#DIM</code> / <code>#DIMS</code> 等用户自定义变量；</li><li><code>IF</code> / <code>REPEAT</code> / <code>FOR</code> / <code>SELECTCASE</code> 等更丰富的复合语句；</li><li>三元运算、字符串拼接、正则表达式等表达式能力；</li><li>用户自定义函数、头文件、宏……</li></ul><p>我们这套教程里讲的大部分内容，其实都是 Emuera 的语法。想看清 Emuera 与 Eramaker 到底有哪些不同，可以专门阅读<a href="./../translation/Difference.html">与 Eramaker 的差异</a>。</p><h2 id="改造版与社区" tabindex="-1">改造版与社区 <a class="header-anchor" href="#改造版与社区" aria-label="Permalink to “改造版与社区”">​</a></h2><p>Emuera 本身也在社区中衍生出许多<strong>改造版</strong>（比如各种“私家版”、EM+EE 等），它们在 Emuera 的基础上又添加了图片、动画、工具提示、更多内置函数等功能。</p><p>这对开发者的意义是：<strong>同一个脚本，在不同改造版里的表现可能不同</strong>。写游戏时，最好先弄清楚目标玩家用的是哪一款引擎，再决定能用哪些特性。</p><h2 id="erabasic-我们写的语言" tabindex="-1">EraBasic：我们写的语言 <a class="header-anchor" href="#erabasic-我们写的语言" aria-label="Permalink to “EraBasic：我们写的语言”">​</a></h2><p>不管是 Eramaker 还是 Emuera，我们写的脚本语言都叫 <strong>EraBasic</strong>。</p><p>它是一门为“文字 + 数值”游戏量身定做的脚本语言：没有类的概念，没有复杂的内存管理，但非常适合快速地把玩法原型写出来。它的设计目标从来不是“强大”，而是“让创作者能立刻上手”。</p><h2 id="这个项目" tabindex="-1">这个项目 <a class="header-anchor" href="#这个项目" aria-label="Permalink to “这个项目”">​</a></h2><p>本中文文档项目（ECD）的目标，是把 Eramaker 与 Emuera 的官方文档完整地翻译过来，并补充面向中文使用者的原创教程与参考。</p><ul><li>想从零开始：请回到<a href="./Quick_Start.html">快速开始</a>；</li><li>想系统学习：请进入<a href="./tutorials/">入门教程</a>；</li><li>想查阅命令与变量：请移步<a href="./../translation/">参考</a>区域。</li></ul><p>历史的车轮还在往前，而你的游戏，就是下一段故事。</p>`,22)]])}var s=r(a,[[`render`,o]]);export{i as __pageData,s as default};